import { NextRequest, NextResponse } from "next/server";
import { adminAuth, adminDb } from "@/lib/firebaseAdmin";

export async function POST(request: NextRequest) {
  try {
    console.log("Register endpoint called");
    const { email, password, fullName, department } = await request.json();
    console.log("Request data:", {
      email,
      fullName,
      department,
      passwordLength: password?.length,
    });

    // Validate inputs
    if (!email || !password || !fullName || !department) {
      console.log("Validation failed: missing fields");
      return NextResponse.json(
        { error: "All fields are required" },
        { status: 400 },
      );
    }

    if (password.length < 6) {
      console.log("Validation failed: password too short");
      return NextResponse.json(
        { error: "Password must be at least 6 characters" },
        { status: 400 },
      );
    }

    console.log("Checking if user exists...");
    // Check if user already exists in Firestore
    try {
      const existingUserQuery = await adminDb
        .collection("users")
        .where("email", "==", email)
        .limit(1)
        .get();

      if (!existingUserQuery.empty) {
        console.log("User already exists");
        return NextResponse.json(
          { error: "Email already exists" },
          { status: 400 },
        );
      }
    } catch (firestoreCheckError: any) {
      console.warn(
        "Could not check user existence in Firestore:",
        firestoreCheckError.message,
      );
      // Continue anyway - we'll try to create the user and Firestore write will fail if user exists
    }

    console.log("Creating Firebase user...");
    // Create user in Firebase Authentication
    const userRecord = await adminAuth.createUser({
      email,
      password,
      displayName: fullName,
    });
    console.log("Firebase user created:", userRecord.uid);

    console.log("Storing user in Firestore...");
    // Store user data in Firestore with approval status
    try {
      await adminDb
        .collection("users")
        .doc(userRecord.uid)
        .set({
          uid: userRecord.uid,
          email,
          name: fullName,
          displayName: fullName,
          department,
          role: "faculty",
          roles: ["faculty"],
          approved: false,
          banned: false,
          createdAt: new Date(),
          updatedAt: new Date(),
        });
      console.log("User stored in Firestore successfully");
    } catch (firestoreError: any) {
      console.error("Firestore error:", firestoreError.message);
      // If Firestore fails, still return success since the user was created in Auth
      // The user can be added to Firestore manually or via admin panel
      console.warn("Continuing with registration despite Firestore error");
    }

    return NextResponse.json({
      message: "User registered successfully. Awaiting admin approval.",
      user: {
        id: userRecord.uid,
        email,
        name: fullName,
        department,
      },
    });
  } catch (error: any) {
    console.error("Register error:", error);

    // Handle Firebase specific errors
    if (error.code === "auth/email-already-exists") {
      return NextResponse.json(
        { error: "Email already exists" },
        { status: 400 },
      );
    }

    if (error.code === "auth/invalid-email") {
      return NextResponse.json(
        { error: "Invalid email address" },
        { status: 400 },
      );
    }

    if (error.code === "auth/weak-password") {
      return NextResponse.json(
        { error: "Password is too weak" },
        { status: 400 },
      );
    }

    console.error("Register error full details:", {
      code: error.code,
      message: error.message,
      error: error,
    });

    return NextResponse.json(
      { error: error.message || "Internal server error" },
      { status: 500 },
    );
  }
}
